-- Add public_id column with default, avoiding long lock waits
DO $$
DECLARE
  lock_acquired boolean := false;
BEGIN
  WHILE NOT lock_acquired LOOP
    BEGIN
      EXECUTE 'LOCK TABLE orders IN ACCESS EXCLUSIVE MODE NOWAIT';
      lock_acquired := true;
    EXCEPTION WHEN lock_not_available THEN
      PERFORM pg_sleep(0.1);
    END;
  END LOOP;
  EXECUTE 'ALTER TABLE orders ADD COLUMN public_id uuid DEFAULT gen_random_uuid()';
END $$;

-- Backfill existing rows in batches with commits
CREATE PROCEDURE backfill_orders_public_id()
LANGUAGE plpgsql
AS $$
DECLARE
  batch_size bigint := 10000;
  min_id bigint;
  max_id bigint;
  current_min bigint;
BEGIN
  SELECT min(id), max(id) INTO min_id, max_id FROM orders WHERE public_id IS NULL;
  IF min_id IS NULL THEN
    RETURN;
  END IF;
  current_min := min_id;
  WHILE current_min <= max_id LOOP
    UPDATE orders SET public_id = gen_random_uuid()
    WHERE public_id IS NULL AND id >= current_min AND id < current_min + batch_size;
    COMMIT;
    current_min := current_min + batch_size;
  END LOOP;
END $$;

CALL backfill_orders_public_id();

DROP PROCEDURE backfill_orders_public_id();

